it("restores capability view state before saving a non-empty standard replay", async () => {
	type RestoreResult = {
		isError: false;
		structuredContent: {
			found: true;
			tool_name: string;
			data: { title: string };
			view_state: { "details.open": true };
		};
	};
	const compatParent: CompatParent = Object.assign(new EventTarget(), {
		location: { origin: "https://chatgpt.com" },
	});
	Object.defineProperty(window, "parent", {
		configurable: true,
		value: compatParent,
	});
	let resolveRestore!: (result: RestoreResult) => void;
	const restore = new Promise<RestoreResult>((resolve) => {
		resolveRestore = resolve;
	});
	bridge.callServerTool.mockImplementation(async ({ name }) => {
		if (name === "restore_lobu_app_result") return restore;
		if (name === "save_lobu_app_state") {
			return { isError: false, structuredContent: { saved: true } };
		}
		return { isError: false };
	});

	const { Provider, useMcpApp } = await import("./host");
	function Probe() {
		const { data, viewState } = useMcpApp<{ title: string }>();
		return (
			<>
				<span>{data?.title}</span>
				<span>{String(viewState["details.open"])}</span>
			</>
		);
	}

	render(
		<Provider devMock={{ title: "Development result" }}>
			<Probe />
		</Provider>,
	);
	await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
	act(() => {
		for (const handler of bridge.listeners.get("toolresult") ?? []) {
			handler({
				structuredContent: { title: "Current replayed result" },
				_meta: {
					"lobu/mcp-app-snapshot-capability": "standard-replay-token",
				},
			});
		}
	});

	expect(
		await screen.findByText("Current replayed result"),
	).toBeInTheDocument();
	await waitFor(() =>
		expect(bridge.callServerTool).toHaveBeenCalledWith({
			name: "restore_lobu_app_result",
			arguments: { snapshot_capability: "standard-replay-token" },
		}),
	);
	expect(
		bridge.callServerTool.mock.calls.filter(
			([request]) => request.name === "save_lobu_app_state",
		),
	).toHaveLength(0);

	await act(async () => {
		resolveRestore({
			isError: false,
			structuredContent: {
				found: true,
				tool_name: "query_sdk",
				data: { title: "Historical snapshot data" },
				view_state: { "details.open": true },
			},
		});
		await restore;
	});

	expect(await screen.findByText("true")).toBeInTheDocument();
	expect(screen.getByText("Current replayed result")).toBeInTheDocument();
	expect(
		screen.queryByText("Historical snapshot data"),
	).not.toBeInTheDocument();
	await waitFor(() =>
		expect(bridge.callServerTool).toHaveBeenCalledWith({
			name: "save_lobu_app_state",
			arguments: {
				tool_name: "query_sdk",
				view_state: { "details.open": true },
				snapshot_capability: "standard-replay-token",
			},
			_meta: {
				"lobu/mcp-app-snapshot-capability": "standard-replay-token",
			},
		}),
	);
});

