			name: "save_lobu_app_state",
			arguments: {
				tool_name: "query_sdk",
				view_state: { "details.open": true },
				snapshot_capability: "duplicate-token",
			},
			_meta: {
				"lobu/mcp-app-snapshot-capability": "duplicate-token",
			},
		}),
	);
	expect(
		bridge.callServerTool.mock.calls.filter(
			([request]) => request.name === "restore_lobu_app_result",
		),
	).toHaveLength(1);
});

